from riko import Context
from riko.modules._subpipe import mark_subpipe
from riko.modules.itembuilder import pipe as itembuilder
from riko.modules.loop import pipe as loop
from riko.modules.tokenizer import pipe as tokenizer
from riko.types.modules import ItemBuilderRawConf, TokenizerRawConf


def pipe(item=None, context: Context | None = None, **_):
    if context and context.describe_input:
        _OUTPUT = []
    elif context and context.describe_dependencies:
        _OUTPUT = ["itembuilder", "loop"]
    else:
        sw_1 = itembuilder(
            item,
            conf=ItemBuilderRawConf(
                {
                    "attrs": [
                        {
                            "key": {"type": "text", "value": "title"},
                            "value": {"type": "text", "value": "a b c"},
                        }
                    ]
                }
            ),
            context=context,
        )
        sw_2 = loop(
            sw_1,
            conf=TokenizerRawConf({"delimiter": {"type": "text", "value": " "}}),
            emit=False,
            assign="tokens",
            field="title",
            count="all",
            context=context,
            embed=tokenizer,
        )
        _OUTPUT = sw_2

    return _OUTPUT


mark_subpipe(pipe, subtype="source")


if __name__ == "__main__":
    for i in pipe():
        print(i)
